reference_solution:
def splitArray(nums, k):
    def parts(cap):
        c, cur = 1, 0
        for x in nums:
            if cur + x > cap:
                c += 1
                cur = 0
            cur += x
        return c
    lo, hi = max(nums), sum(nums)
    while lo < hi:
        mid = (lo + hi) // 2
        if parts(mid) <= k:
            hi = mid
        else:
            lo = mid + 1
    return lo

brute_force_solution:
def splitArray(nums, k):
    n = len(nums)
    INF = float('inf')
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            for p in range(i):
                if dp[p][j - 1] < INF:
                    dp[i][j] = min(dp[i][j], max(dp[p][j - 1], pre[i] - pre[p]))
    return dp[n][k]

